CREATE TABLE operations.correction_submissions (id uuid PRIMARY KEY NOT NULL, release_id text NOT NULL, seat_cycle_id text, field_path text NOT NULL, explanation text NOT NULL, source_url text, submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT correction_submissions_release_id_data_releases_id_fk FOREIGN KEY(release_id) REFERENCES public.data_releases(id), CONSTRAINT correction_submissions_field_path_ck CHECK (field_path IN ('identity.current_holder','identity.party','identity.occupancy','biography.bioguide_id','biography.birth_date','biography.other','elections','finance','demographics','district_boundary','sources','other')), CONSTRAINT correction_submissions_release_id_ck CHECK (release_id ~ '^rel_[A-Za-z0-9_-]{1,128}$'), CONSTRAINT correction_submissions_seat_cycle_id_ck CHECK (seat_cycle_id IS NULL OR seat_cycle_id ~ '^seat_[A-Za-z0-9_-]{1,128}$'), CONSTRAINT correction_submissions_explanation_ck CHECK (char_length(explanation) BETWEEN 20 AND 4000 AND octet_length(explanation)<=16384 AND explanation=btrim(explanation,E' \n\t') AND regexp_replace(explanation,E'[\n\t]','','g') !~ '[[:cntrl:]]'));
ALTER TABLE operations.correction_submissions ADD CONSTRAINT correction_submissions_release_id_seat_cycle_id_seat_cycles_release_id_id_fk FOREIGN KEY(release_id,seat_cycle_id) REFERENCES public.seat_cycles(release_id,id);
CREATE TABLE operations.correction_review_events (submission_id uuid NOT NULL, sequence integer NOT NULL, from_status text, to_status text NOT NULL, reason_code text NOT NULL, candidate_release_id text, approved_snapshot_id text, approved_snapshot_checksum text, actor text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(submission_id,sequence), CONSTRAINT correction_review_events_submission_id_correction_submissions_id_fk FOREIGN KEY(submission_id) REFERENCES operations.correction_submissions(id), CONSTRAINT correction_review_events_sequence_ck CHECK(sequence>=1), CONSTRAINT correction_review_events_status_ck CHECK(to_status IN ('submitted','in_review','accepted','queued','rejected','incorporated')), CONSTRAINT correction_review_events_reason_ck CHECK(reason_code IN ('submitted','triaged','not_actionable','approved','needs_candidate','candidate_ready','withdrawn','incorporated')), CONSTRAINT correction_review_events_snapshot_checksum_ck CHECK ((to_status='incorporated')=(approved_snapshot_checksum IS NOT NULL) AND (approved_snapshot_checksum IS NULL OR approved_snapshot_checksum ~ '^[a-f0-9]{64}$')));
ALTER TABLE operations.correction_review_events ADD CONSTRAINT correction_review_events_candidate_release_id_data_releases_id_fk FOREIGN KEY(candidate_release_id) REFERENCES public.data_releases(id);
ALTER TABLE operations.correction_review_events ADD CONSTRAINT correction_review_events_candidate_release_id_approved_snapshot_id_source_snapshots_release_id_id_fk FOREIGN KEY(candidate_release_id,approved_snapshot_id) REFERENCES public.source_snapshots(release_id,id);
CREATE TABLE operations.correction_idempotency_keys (key_hash bytea PRIMARY KEY NOT NULL, payload_fingerprint bytea NOT NULL, correction_id uuid, outcome text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL, CONSTRAINT correction_idempotency_keys_correction_id_correction_submissions_id_fk FOREIGN KEY(correction_id) REFERENCES operations.correction_submissions(id), CONSTRAINT correction_idempotency_keys_hash_ck CHECK(octet_length(key_hash)=32 AND octet_length(payload_fingerprint)=32), CONSTRAINT correction_idempotency_keys_outcome_ck CHECK((outcome='accepted' AND correction_id IS NOT NULL) OR (outcome='target_unavailable' AND correction_id IS NULL)), CONSTRAINT correction_idempotency_keys_expiry_ck CHECK(expires_at>created_at AND expires_at<=created_at+interval '24 hours'));
CREATE TABLE operations.correction_rate_limit_buckets (bucket_kind text NOT NULL, subject_hash bytea NOT NULL, window_started_at timestamptz NOT NULL, count integer NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(bucket_kind,subject_hash,window_started_at), CONSTRAINT correction_rate_limit_buckets_kind_ck CHECK(bucket_kind IN('attempt_minute','subject_hour','global_minute','global_day')), CONSTRAINT correction_rate_limit_buckets_hash_ck CHECK(octet_length(subject_hash)=32), CONSTRAINT correction_rate_limit_buckets_count_ck CHECK(count BETWEEN 1 AND CASE WHEN bucket_kind='attempt_minute' THEN 20 WHEN bucket_kind='subject_hour' THEN 5 WHEN bucket_kind='global_minute' THEN 100 ELSE 5000 END), CONSTRAINT correction_rate_limit_buckets_expiry_ck CHECK(expires_at>window_started_at AND expires_at<=window_started_at+interval '48 hours'));
CREATE UNIQUE INDEX correction_idempotency_keys_correction_uq ON operations.correction_idempotency_keys(correction_id) WHERE correction_id IS NOT NULL;
CREATE INDEX correction_controls_expiry_idx ON operations.correction_idempotency_keys(expires_at);
CREATE INDEX correction_rate_controls_expiry_idx ON operations.correction_rate_limit_buckets(expires_at);
CREATE INDEX correction_reviewer_queue_idx ON operations.correction_review_events(to_status,occurred_at,submission_id) WHERE to_status IN ('submitted','in_review','accepted','queued');
CREATE INDEX correction_submissions_release_seat_idx ON operations.correction_submissions(release_id,seat_cycle_id,id);
CREATE INDEX correction_submissions_submitted_at_id_idx ON operations.correction_submissions(submitted_at,id);
