CREATE OR REPLACE FUNCTION operations.canonical_correction_source_url(p_url text) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,operations,pg_temp AS $$
DECLARE host text; route text; path text; query text; canonical text; previous text;
BEGIN
 IF octet_length(p_url) NOT BETWEEN 1 AND 8192 OR char_length(p_url)>2000 OR p_url<>btrim(p_url) OR p_url !~ '^[\x21-\x7e]+$' OR p_url ~ '[@#[:space:]]' OR p_url !~ '^https://[A-Za-z0-9.-]+([/?][A-Za-z0-9._~!$&''()*+,;=:/?%\-]*)?$' THEN RETURN NULL; END IF;
 host:=substring(p_url FROM '^https://([^/?]+)'); route:=substring(p_url FROM '^https://[^/?]+(.*)$');
 IF host IS NULL OR host !~ '^([A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$' OR lower(split_part(host,'.',array_length(string_to_array(host,'.'),1))) IN ('localhost','local','internal','test','invalid') OR host ~ '^([0-9]{1,3}\.){3}[0-9]{1,3}$' OR regexp_replace(p_url,'%[0-9A-F]{2}','','g') ~ '%' OR p_url ~ '/(\.|%2E){1,2}(/|\?|$)' THEN RETURN NULL; END IF;
 route:=CASE WHEN route LIKE '?' || '%' THEN '/' || route ELSE coalesce(nullif(route,''),'/') END; path:=split_part(route,'?',1); query:=CASE WHEN position('?' IN route)>0 THEN substring(route FROM position('?' IN route)) ELSE '' END;
 LOOP previous:=path; path:=regexp_replace(path,'/\./','/','g'); path:=regexp_replace(path,'/[^/]+/\.\./','/','g'); path:=regexp_replace(path,'^/\.\./','/','g'); EXIT WHEN path=previous; END LOOP;
 IF path='/.' THEN path:='/'; ELSIF path LIKE '%/.' THEN path:=left(path,char_length(path)-1); END IF;
 canonical:='https://' || lower(host) || replace(path || query,'''','%27');
 IF octet_length(canonical)>8192 OR char_length(canonical)>2000 THEN RETURN NULL; END IF;
 RETURN canonical;
END $$;
ALTER TABLE operations.correction_submissions ADD CONSTRAINT correction_submissions_source_url_ck CHECK(source_url IS NULL OR operations.canonical_correction_source_url(source_url)=source_url);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='dsa_seats_correction_intake') THEN CREATE ROLE dsa_seats_correction_intake NOLOGIN; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='dsa_seats_correction_reviewer') THEN CREATE ROLE dsa_seats_correction_reviewer NOLOGIN; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='dsa_seats_correction_maintenance') THEN CREATE ROLE dsa_seats_correction_maintenance NOLOGIN; END IF; END $$;
DO $$
DECLARE correction_roles text[]:=ARRAY['dsa_seats_correction_intake','dsa_seats_correction_reviewer','dsa_seats_correction_maintenance']; other_roles text[]:=ARRAY['dsa_seats_web','dsa_seats_ingest','dsa_seats_release_preflight','dsa_seats_release_operator','dsa_seats_migration_owner'];
BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=ANY(correction_roles) AND (rolcanlogin OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls)) THEN RAISE EXCEPTION 'correction roles must be constrained NOLOGIN roles'; END IF;
 IF EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member JOIN pg_roles granted ON granted.oid=m.roleid WHERE (member.rolname=ANY(correction_roles) AND granted.rolname=ANY(correction_roles||other_roles)) OR (member.rolname=ANY(other_roles) AND granted.rolname=ANY(correction_roles))) THEN RAISE EXCEPTION 'correction roles must not have cross-memberships'; END IF;
END $$;
CREATE OR REPLACE FUNCTION operations.forbid_correction_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,operations,pg_temp AS $$ BEGIN RAISE EXCEPTION 'correction records are immutable' USING ERRCODE='55000'; END $$;
CREATE TRIGGER correction_submissions_immutable BEFORE UPDATE OR DELETE ON operations.correction_submissions FOR EACH ROW EXECUTE FUNCTION operations.forbid_correction_mutation();
CREATE TRIGGER correction_review_events_append_only BEFORE UPDATE OR DELETE ON operations.correction_review_events FOR EACH ROW EXECUTE FUNCTION operations.forbid_correction_mutation();
ALTER TABLE operations.correction_submissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE operations.correction_review_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE operations.correction_idempotency_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE operations.correction_rate_limit_buckets ENABLE ROW LEVEL SECURITY;
