CREATE OR REPLACE FUNCTION operations.consume_correction_attempt_v1(p_subject_hash bytea) RETURNS TABLE(allowed boolean,retry_after integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations,pg_temp AS $$
DECLARE now_at timestamptz:=clock_timestamp(); n integer;
BEGIN
 IF NOT pg_has_role(session_user,'dsa_seats_correction_intake','member') OR pg_has_role(session_user,'dsa_seats_correction_reviewer','member') OR pg_has_role(session_user,'dsa_seats_correction_maintenance','member') OR pg_has_role(session_user,'dsa_seats_web','member') OR pg_has_role(session_user,'dsa_seats_ingest','member') OR pg_has_role(session_user,'dsa_seats_release_preflight','member') OR pg_has_role(session_user,'dsa_seats_release_operator','member') OR pg_has_role(session_user,'dsa_seats_migration_owner','member') THEN RAISE EXCEPTION 'intake role exclusively required' USING ERRCODE='42501'; END IF;
 IF p_subject_hash IS NULL OR octet_length(p_subject_hash)<>32 THEN RAISE EXCEPTION 'subject hash must be 32 bytes' USING ERRCODE='22023'; END IF;
 INSERT INTO operations.correction_rate_limit_buckets VALUES('attempt_minute',p_subject_hash,date_trunc('minute',now_at),1,date_trunc('minute',now_at)+interval '2 minutes') ON CONFLICT(bucket_kind,subject_hash,window_started_at) DO UPDATE SET count=operations.correction_rate_limit_buckets.count+1 WHERE operations.correction_rate_limit_buckets.count<20 RETURNING count INTO n;
 IF FOUND THEN RETURN QUERY SELECT true,NULL::integer; ELSE RETURN QUERY SELECT false,ceil(extract(epoch FROM(date_trunc('minute',now_at)+interval '1 minute'-now_at)))::integer; END IF;
END $$;
CREATE OR REPLACE FUNCTION operations.submit_correction_v1(p_key_hash bytea,p_subject_hash bytea,p_release_id text,p_seat_cycle_id text,p_field_path text,p_explanation text,p_source_url text) RETURNS TABLE(outcome text,correction_id uuid,created boolean,retry_after integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations,public,pg_temp AS $$
DECLARE now_at timestamptz:=clock_timestamp(); normalized_explanation text:=btrim(replace(p_explanation,E'\r\n',E'\n'),E' \n\t'); normalized_url text:=operations.canonical_correction_source_url(p_source_url); fp bytea; existing operations.correction_idempotency_keys%ROWTYPE; new_id uuid; n integer; retry integer;
BEGIN
 IF NOT pg_has_role(session_user,'dsa_seats_correction_intake','member') OR pg_has_role(session_user,'dsa_seats_correction_reviewer','member') OR pg_has_role(session_user,'dsa_seats_correction_maintenance','member') OR pg_has_role(session_user,'dsa_seats_web','member') OR pg_has_role(session_user,'dsa_seats_ingest','member') OR pg_has_role(session_user,'dsa_seats_release_preflight','member') OR pg_has_role(session_user,'dsa_seats_release_operator','member') OR pg_has_role(session_user,'dsa_seats_migration_owner','member') THEN RAISE EXCEPTION 'intake role exclusively required' USING ERRCODE='42501'; END IF;
 IF p_key_hash IS NULL OR p_subject_hash IS NULL OR p_release_id IS NULL OR p_field_path IS NULL OR p_explanation IS NULL OR octet_length(p_key_hash)<>32 OR octet_length(p_subject_hash)<>32 OR p_release_id !~ '^rel_[A-Za-z0-9_-]{1,128}$' OR (p_seat_cycle_id IS NOT NULL AND p_seat_cycle_id !~ '^seat_[A-Za-z0-9_-]{1,128}$') OR p_field_path NOT IN('identity.current_holder','identity.party','identity.occupancy','biography.bioguide_id','biography.birth_date','biography.other','elections','finance','demographics','district_boundary','sources','other') OR char_length(normalized_explanation) NOT BETWEEN 20 AND 4000 OR octet_length(normalized_explanation)>16384 OR regexp_replace(normalized_explanation,E'[\n\t]','','g') ~ '[[:cntrl:]]' OR (p_source_url IS NOT NULL AND normalized_url IS NULL) THEN RETURN QUERY SELECT 'invalid_request',NULL::uuid,false,NULL::integer; RETURN; END IF;
 fp:=digest(jsonb_build_object('release_id',p_release_id,'seat_cycle_id',p_seat_cycle_id,'field_path',p_field_path,'explanation',normalized_explanation,'source_url',normalized_url)::text,'sha256'); PERFORM pg_advisory_xact_lock(hashtextextended(encode(p_key_hash,'hex'),0)); DELETE FROM operations.correction_idempotency_keys WHERE key_hash=p_key_hash AND expires_at<=now_at; SELECT * INTO existing FROM operations.correction_idempotency_keys WHERE key_hash=p_key_hash;
 IF FOUND THEN IF existing.payload_fingerprint=fp THEN RETURN QUERY SELECT existing.outcome,existing.correction_id,false,NULL::integer; ELSE RETURN QUERY SELECT 'idempotency_conflict',NULL::uuid,false,NULL::integer; END IF; RETURN; END IF;
 INSERT INTO operations.correction_rate_limit_buckets VALUES('global_minute',digest('global','sha256'),date_trunc('minute',now_at),1,date_trunc('minute',now_at)+interval '2 minutes') ON CONFLICT(bucket_kind,subject_hash,window_started_at) DO UPDATE SET count=operations.correction_rate_limit_buckets.count+1 WHERE operations.correction_rate_limit_buckets.count<100 RETURNING count INTO n; IF NOT FOUND THEN retry:=ceil(extract(epoch FROM(date_trunc('minute',now_at)+interval '1 minute'-now_at)))::integer; RETURN QUERY SELECT 'rate_limited',NULL::uuid,false,retry; RETURN; END IF;
 INSERT INTO operations.correction_rate_limit_buckets VALUES('global_day',digest('global','sha256'),date_trunc('day',now_at),1,date_trunc('day',now_at)+interval '2 days') ON CONFLICT(bucket_kind,subject_hash,window_started_at) DO UPDATE SET count=operations.correction_rate_limit_buckets.count+1 WHERE operations.correction_rate_limit_buckets.count<5000 RETURNING count INTO n; IF NOT FOUND THEN retry:=ceil(extract(epoch FROM(date_trunc('day',now_at)+interval '1 day'-now_at)))::integer; RETURN QUERY SELECT 'rate_limited',NULL::uuid,false,retry; RETURN; END IF;
 INSERT INTO operations.correction_rate_limit_buckets VALUES('subject_hour',p_subject_hash,date_trunc('hour',now_at),1,date_trunc('hour',now_at)+interval '2 hours') ON CONFLICT(bucket_kind,subject_hash,window_started_at) DO UPDATE SET count=operations.correction_rate_limit_buckets.count+1 WHERE operations.correction_rate_limit_buckets.count<5 RETURNING count INTO n; IF NOT FOUND THEN DELETE FROM operations.correction_rate_limit_buckets WHERE bucket_kind='global_day' AND subject_hash=digest('global','sha256') AND window_started_at=date_trunc('day',now_at) AND count=1; UPDATE operations.correction_rate_limit_buckets SET count=count-1 WHERE bucket_kind='global_day' AND subject_hash=digest('global','sha256') AND window_started_at=date_trunc('day',now_at) AND count>1; DELETE FROM operations.correction_rate_limit_buckets WHERE bucket_kind='global_minute' AND subject_hash=digest('global','sha256') AND window_started_at=date_trunc('minute',now_at) AND count=1; UPDATE operations.correction_rate_limit_buckets SET count=count-1 WHERE bucket_kind='global_minute' AND subject_hash=digest('global','sha256') AND window_started_at=date_trunc('minute',now_at) AND count>1; retry:=ceil(extract(epoch FROM(date_trunc('hour',now_at)+interval '1 hour'-now_at)))::integer; RETURN QUERY SELECT 'rate_limited',NULL::uuid,false,retry; RETURN; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.data_releases WHERE id=p_release_id AND(status='published' OR(status='retired' AND published_at IS NOT NULL))) OR(p_seat_cycle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.seat_cycles WHERE release_id=p_release_id AND id=p_seat_cycle_id)) THEN INSERT INTO operations.correction_idempotency_keys(key_hash,payload_fingerprint,correction_id,outcome,created_at,expires_at) VALUES(p_key_hash,fp,NULL,'target_unavailable',now_at,now_at+interval '24 hours'); RETURN QUERY SELECT 'target_unavailable',NULL::uuid,false,NULL::integer; RETURN; END IF;
 new_id:=gen_random_uuid(); INSERT INTO operations.correction_submissions(id,release_id,seat_cycle_id,field_path,explanation,source_url,submitted_at) VALUES(new_id,p_release_id,p_seat_cycle_id,p_field_path,normalized_explanation,normalized_url,now_at); INSERT INTO operations.correction_review_events(submission_id,sequence,from_status,to_status,reason_code,actor,occurred_at) VALUES(new_id,1,NULL,'submitted','submitted',session_user,now_at); INSERT INTO operations.correction_idempotency_keys(key_hash,payload_fingerprint,correction_id,outcome,created_at,expires_at) VALUES(p_key_hash,fp,new_id,'accepted',now_at,now_at+interval '24 hours'); RETURN QUERY SELECT 'accepted',new_id,true,NULL::integer;
END $$;
CREATE OR REPLACE FUNCTION operations.transition_correction_v1(p_correction_id uuid,p_expected_sequence integer,p_expected_status text,p_to_status text,p_reason_code text,p_candidate_release_id text,p_approved_snapshot_id text) RETURNS TABLE(outcome text,sequence integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations,public,pg_temp AS $$
DECLARE s operations.correction_submissions%ROWTYPE; latest operations.correction_review_events%ROWTYPE; checksum text; next_seq integer;
BEGIN
 IF NOT pg_has_role(session_user,'dsa_seats_correction_reviewer','member') OR pg_has_role(session_user,'dsa_seats_correction_intake','member') OR pg_has_role(session_user,'dsa_seats_correction_maintenance','member') OR pg_has_role(session_user,'dsa_seats_web','member') OR pg_has_role(session_user,'dsa_seats_ingest','member') OR pg_has_role(session_user,'dsa_seats_release_preflight','member') OR pg_has_role(session_user,'dsa_seats_release_operator','member') OR pg_has_role(session_user,'dsa_seats_migration_owner','member') THEN RAISE EXCEPTION 'reviewer role exclusively required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('dsa_seats_release_promotion')); IF p_candidate_release_id IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtext('dsa_seats_release:'||p_candidate_release_id)); END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_correction_id::text,0)); SELECT * INTO s FROM operations.correction_submissions WHERE id=p_correction_id; SELECT * INTO latest FROM operations.correction_review_events WHERE submission_id=p_correction_id ORDER BY sequence DESC LIMIT 1;
 IF NOT FOUND OR latest.sequence<>p_expected_sequence OR latest.to_status<>p_expected_status THEN RETURN QUERY SELECT 'conflict',NULL::integer; RETURN; END IF;
 IF NOT ((p_expected_status='submitted' AND p_to_status='in_review' AND p_reason_code='triaged') OR(p_expected_status='submitted' AND p_to_status='rejected' AND p_reason_code IN('not_actionable','withdrawn')) OR(p_expected_status='in_review' AND p_to_status='accepted' AND p_reason_code='approved') OR(p_expected_status='in_review' AND p_to_status='rejected' AND p_reason_code IN('not_actionable','withdrawn')) OR(p_expected_status='accepted' AND p_to_status='queued' AND p_reason_code='needs_candidate') OR(p_expected_status='accepted' AND p_to_status='rejected' AND p_reason_code IN('not_actionable','withdrawn')) OR(p_expected_status='queued' AND p_to_status='accepted' AND p_reason_code='candidate_ready') OR(p_expected_status='queued' AND p_to_status='incorporated' AND p_reason_code='incorporated')) THEN RETURN QUERY SELECT 'invalid_transition',NULL::integer; RETURN; END IF;
 IF p_to_status NOT IN('queued','incorporated') AND(p_candidate_release_id IS NOT NULL OR p_approved_snapshot_id IS NOT NULL) THEN RETURN QUERY SELECT 'invalid_transition',NULL::integer; RETURN; END IF;
 IF p_to_status='queued' AND(p_candidate_release_id IS NULL OR p_approved_snapshot_id IS NOT NULL OR NOT EXISTS(WITH RECURSIVE lineage(id,previous_release_id,path) AS(SELECT id,previous_release_id,ARRAY[id] FROM public.data_releases WHERE id=p_candidate_release_id AND status='candidate' UNION ALL SELECT r.id,r.previous_release_id,l.path||r.id FROM public.data_releases r JOIN lineage l ON r.id=l.previous_release_id WHERE NOT r.id=ANY(l.path)) SELECT 1 FROM lineage WHERE id=s.release_id)) THEN RETURN QUERY SELECT 'invalid_transition',NULL::integer; RETURN; END IF;
 IF p_to_status='incorporated' AND(p_candidate_release_id IS DISTINCT FROM latest.candidate_release_id OR p_candidate_release_id IS NULL OR p_approved_snapshot_id IS NULL) THEN RETURN QUERY SELECT 'invalid_transition',NULL::integer; RETURN; END IF;
 IF p_to_status='incorporated' THEN SELECT checksum_sha256 INTO checksum FROM public.source_snapshots WHERE release_id=p_candidate_release_id AND id=p_approved_snapshot_id AND usage_status='approved'; IF checksum IS NULL OR NOT EXISTS(WITH RECURSIVE lineage(id,previous_release_id,path) AS(SELECT id,previous_release_id,ARRAY[id] FROM public.data_releases WHERE id=p_candidate_release_id AND status='candidate' UNION ALL SELECT r.id,r.previous_release_id,l.path||r.id FROM public.data_releases r JOIN lineage l ON r.id=l.previous_release_id WHERE NOT r.id=ANY(l.path)) SELECT 1 FROM lineage WHERE id=s.release_id) THEN RETURN QUERY SELECT 'invalid_transition',NULL::integer; RETURN; END IF; END IF;
 next_seq:=latest.sequence+1; INSERT INTO operations.correction_review_events(submission_id,sequence,from_status,to_status,reason_code,candidate_release_id,approved_snapshot_id,approved_snapshot_checksum,actor) VALUES(p_correction_id,next_seq,p_expected_status,p_to_status,p_reason_code,p_candidate_release_id,p_approved_snapshot_id,checksum,session_user); RETURN QUERY SELECT 'transitioned',next_seq;
END $$;
CREATE OR REPLACE FUNCTION operations.list_corrections_v1(p_after_submitted_at timestamptz DEFAULT NULL,p_after_id uuid DEFAULT NULL,p_limit integer DEFAULT 50) RETURNS TABLE(id uuid,release_id text,seat_cycle_id text,field_path text,explanation text,source_url text,submitted_at timestamptz,status text,sequence integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,operations,pg_temp AS $$ BEGIN IF NOT pg_has_role(session_user,'dsa_seats_correction_reviewer','member') OR pg_has_role(session_user,'dsa_seats_correction_intake','member') OR pg_has_role(session_user,'dsa_seats_correction_maintenance','member') OR pg_has_role(session_user,'dsa_seats_web','member') OR pg_has_role(session_user,'dsa_seats_ingest','member') OR pg_has_role(session_user,'dsa_seats_release_preflight','member') OR pg_has_role(session_user,'dsa_seats_release_operator','member') OR pg_has_role(session_user,'dsa_seats_migration_owner','member') THEN RAISE EXCEPTION 'reviewer role exclusively required' USING ERRCODE='42501'; END IF; IF (p_after_submitted_at IS NULL) <> (p_after_id IS NULL) THEN RAISE EXCEPTION 'cursor timestamp and id must both be null or present' USING ERRCODE='22023'; END IF; IF p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'limit must be 1..100' USING ERRCODE='22023'; END IF; RETURN QUERY SELECT s.id,s.release_id,s.seat_cycle_id,s.field_path,s.explanation,s.source_url,s.submitted_at,e.to_status,e.sequence FROM operations.correction_submissions s CROSS JOIN LATERAL(SELECT cre.to_status,cre.sequence FROM operations.correction_review_events cre WHERE cre.submission_id=s.id ORDER BY cre.sequence DESC LIMIT 1)e WHERE p_after_submitted_at IS NULL OR(s.submitted_at,s.id)>(p_after_submitted_at,p_after_id) ORDER BY s.submitted_at,s.id LIMIT p_limit; END $$;
CREATE OR REPLACE FUNCTION operations.cleanup_correction_controls_v1() RETURNS TABLE(idempotency_deleted integer,rate_buckets_deleted integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations,pg_temp AS $$ BEGIN IF NOT pg_has_role(session_user,'dsa_seats_correction_maintenance','member') OR pg_has_role(session_user,'dsa_seats_correction_intake','member') OR pg_has_role(session_user,'dsa_seats_correction_reviewer','member') OR pg_has_role(session_user,'dsa_seats_web','member') OR pg_has_role(session_user,'dsa_seats_ingest','member') OR pg_has_role(session_user,'dsa_seats_release_preflight','member') OR pg_has_role(session_user,'dsa_seats_release_operator','member') OR pg_has_role(session_user,'dsa_seats_migration_owner','member') THEN RAISE EXCEPTION 'maintenance role exclusively required' USING ERRCODE='42501'; END IF; DELETE FROM operations.correction_idempotency_keys WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS idempotency_deleted=ROW_COUNT; DELETE FROM operations.correction_rate_limit_buckets WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS rate_buckets_deleted=ROW_COUNT; RETURN NEXT; END $$;
DO $$ DECLARE f text; BEGIN FOR f IN SELECT unnest(ARRAY['canonical_correction_source_url(text)','forbid_correction_mutation()','consume_correction_attempt_v1(bytea)','submit_correction_v1(bytea,bytea,text,text,text,text,text)','transition_correction_v1(uuid,integer,text,text,text,text,text)','list_corrections_v1(timestamp with time zone,uuid,integer)','cleanup_correction_controls_v1()']) LOOP EXECUTE 'ALTER FUNCTION operations.'||f||' OWNER TO dsa_seats_migration_owner'; END LOOP; ALTER SCHEMA operations OWNER TO dsa_seats_migration_owner; ALTER TABLE operations.correction_submissions OWNER TO dsa_seats_migration_owner; ALTER TABLE operations.correction_review_events OWNER TO dsa_seats_migration_owner; ALTER TABLE operations.correction_idempotency_keys OWNER TO dsa_seats_migration_owner; ALTER TABLE operations.correction_rate_limit_buckets OWNER TO dsa_seats_migration_owner; END $$;
REVOKE ALL ON SCHEMA operations FROM PUBLIC,dsa_seats_web,dsa_seats_ingest,dsa_seats_release_preflight,dsa_seats_release_operator; REVOKE ALL ON ALL TABLES IN SCHEMA operations FROM PUBLIC,dsa_seats_web,dsa_seats_ingest,dsa_seats_release_preflight,dsa_seats_release_operator,dsa_seats_correction_intake,dsa_seats_correction_reviewer,dsa_seats_correction_maintenance; REVOKE ALL ON ALL FUNCTIONS IN SCHEMA operations FROM PUBLIC; GRANT USAGE ON SCHEMA operations TO dsa_seats_correction_intake,dsa_seats_correction_reviewer,dsa_seats_correction_maintenance; GRANT EXECUTE ON FUNCTION operations.consume_correction_attempt_v1(bytea),operations.submit_correction_v1(bytea,bytea,text,text,text,text,text) TO dsa_seats_correction_intake; GRANT EXECUTE ON FUNCTION operations.transition_correction_v1(uuid,integer,text,text,text,text,text),operations.list_corrections_v1(timestamptz,uuid,integer) TO dsa_seats_correction_reviewer; GRANT EXECUTE ON FUNCTION operations.cleanup_correction_controls_v1() TO dsa_seats_correction_maintenance;
